export interface TraceSpan {
    /**
     * Unique identifier for the trace span.
     * This is typically a UUID or a similar unique identifier.
     * Undefined for automatically created spans.
     */
    spanId?: string;
    /**
     * The name of the trace span.
     * This is a human-readable name that describes the operation being traced.
     * Only used for manual spans.
     */
    name?: string;
    /**
     * The origin of the trace span.
     * This indicates whether the span was created manually or automatically.
     * - 'manual': The span was created manually by the user.
     * - 'auto': The span was created automatically by the system.
     */
    origin: "manual" | "auto";
    /**
     * Tags associated with the trace span.
     * Tags are key-value pairs that provide additional context about the span.
     */
    tags?: Record<string, string | number | boolean>;
    /**
     * Indicates whether an error occurred during the operation represented by the trace span.
     * If undefined, it means no error occurred.
     * If true, it indicates an error occurred, but the error was handled gracefully and not captured.
     * If an object is provided, it contains details about the error, including:
     * - `message`: A human-readable error message.
     * - `stack`: An optional stack trace of the error.
     * This field is useful for debugging and understanding the context of errors in the trace.
     */
    error?: boolean | {
        cls?: string;
        message: string;
        stack?: string;
        tags?: Record<string, string | number | boolean>;
    };
}
